// expandCropRectToMinSize expands r so that it is at least width×height pixels
// while keeping it within bounds. If bounds is too small to contain a
// width×height rectangle, r is returned unchanged in that axis. The required
// pixels are split evenly between both sides, with any odd pixel going to the
// higher side (right/bottom). If the expanded rectangle exceeds bounds on one
// side, it is shifted to stay within bounds.
func expandCropRectToMinSize(r, bounds image.Rectangle, width, height int) image.Rectangle {
	r.Min.X, r.Max.X = expandAxisToMinSize(r.Min.X, r.Max.X, bounds.Min.X, bounds.Max.X, width)
	r.Min.Y, r.Max.Y = expandAxisToMinSize(r.Min.Y, r.Max.Y, bounds.Min.Y, bounds.Max.Y, height)
	return r
