func expandAxisToMinSize(min, max, boundsMin, boundsMax, size int) (int, int) {
	if boundsMax-boundsMin < size {
		// Bounds too small to fit; leave unchanged.
		return min, max
	}

	extra := size - (max - min)
	if extra <= 0 {
		return min, max
	}

	low := extra / 2
	min -= low
	max += extra - low

	if min < boundsMin {
		max += boundsMin - min
		min = boundsMin
	} else if max > boundsMax {
		min -= max - boundsMax
		max = boundsMax
	}

	return min, max
